package com.cryptox.model; import jakarta.persistence.*; import lombok.*; import java.time.Instant; import java.util.*; @Entity @Table(name="wallet") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class Wallet{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false,unique=true,length=64) String walletId; @Column(nullable=false,unique=true,length=50) String ownerUsername; @OneToMany(mappedBy="wallet",cascade=CascadeType.ALL,orphanRemoval=true,fetch=FetchType.EAGER) @Builder.Default List<WalletBalance> balances=new ArrayList<>(); @Column(nullable=false,updatable=false) Instant createdAt; @PrePersist void pre(){createdAt=Instant.now();}}